import java.io.*;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ' && c != -1) {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);

        int S = fs.nextInt();
        int T = fs.nextInt();

        boolean[][] adj = new boolean[S + 1][S + 1];

        for (int i = 0; i < T; i++) {
            int x = fs.nextInt();
            int y = fs.nextInt();
            adj[x][y] = true;
            adj[y][x] = true;
        }

        int P = fs.nextInt();
        int possibleCount = 0;

        for (int p = 0; p < P; p++) {
            int N = fs.nextInt();

            boolean possible = true;
            int prev = fs.nextInt();

            for (int i = 1; i < N; i++) {
                int cur = fs.nextInt();
                if (possible && !adj[prev][cur]) {
                    possible = false;
                }
                prev = cur;
            }

            if (possible) {
                possibleCount++;
            }
        }

        System.out.println(possibleCount);
    }
}
